"""Literal table parent action spy: application permissions modal remains external."""
from pathlib import Path
import json
r=Path(__file__).resolve().parents[2];o=r/'artifacts/replica/windows-download';lines=(r/'docs/replica/source/original.js').read_text().splitlines()
defs='\n'.join(x for x in lines if x.startswith(('const initial=','let state=','const esc=','const icons=','const icon=','const t=','const btn=','const pill=','const notice=','const heading=','const categoryDefs=','function capabilities(')))
cases=json.loads((r/'docs/replica/source/capabilitytable-input-cases.json').read_text())
script=defs+'\nconst cases='+json.dumps(cases)+";"+r"""
let index=0,permissions=0;const host=document.getElementById('fixtures'),fixture=document.createElement('div');fixture.className='fixture';host.append(fixture);
function set(){const restore=document.activeElement?.id==='CapabilityRow-permissions';const c=cases[index];lang=c.english?'en':'ko';fixture.style.width=(c.width+2)+'px';fixture.innerHTML=capabilities();fixture.querySelectorAll('.page-heading,.notice,.section').forEach(e=>e.remove());fixture.querySelector('[data-action=permissions]').id='CapabilityRow-permissions';fixture.querySelector('table').id='CapabilityTable-source';fixture.querySelector('[data-action=permissions]').onclick=()=>{permissions++;record()};if(restore)fixture.querySelector('[data-action=permissions]').focus({preventScroll:true})}
function tableState(){const shell=fixture.querySelector('.table-shell'),table=fixture.querySelector('table'),r=shell.getBoundingClientRect(),box=e=>{const q=e.getBoundingClientRect();return{x:q.x-r.x,y:q.y-r.y,width:q.width,height:q.height}},button=fixture.querySelector('[data-action=permissions]');return{dpr:devicePixelRatio,id:cases[index].id,shell:box(shell),table:box(table),headers:[...table.querySelectorAll('thead th')].map(box),rows:[...table.querySelectorAll('tbody tr')].map(e=>({box:box(e),cells:[...e.cells].map(box)})),columns:[...table.querySelector('thead tr').cells].map(e=>e.getBoundingClientRect().width),clientWidth:shell.clientWidth,clientHeight:shell.clientHeight,scrollWidth:shell.scrollWidth,scrollHeight:shell.scrollHeight,scrollLeft:shell.scrollLeft,gutter:shell.offsetHeight-shell.clientHeight-2,permissions,english:cases[index].english,attached:fixture.isConnected,permissionsButton:box(button),buttonFocused:document.activeElement===button,viewportFocused:document.activeElement===shell}}
async function record(){const os=new URLSearchParams(location.search).get('os')==='windows'?'windows':'mac';const res=await fetch('/evidence/preflight-capabilitytable-'+os+'-input.json',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(tableState())});if(!res.ok)throw Error('Record failed')}
document.getElementById('CapabilityTable-next').onclick=()=>{index=(index+1)%cases.length;set();record()};document.getElementById('CapabilityTable-mount').onclick=()=>{if(fixture.isConnected)fixture.remove();else host.append(fixture);record()};document.getElementById('CapabilityTable-record').onclick=record;document.getElementById('CapabilityTable-focus').onclick=()=>{fixture.querySelector('[data-action=permissions]').focus({preventScroll:true});record()};document.addEventListener('focusin',()=>setTimeout(record,0));set();setInterval(record,64);
"""
(o/'capabilitytable-input.html').write_text('<!doctype html><meta charset="utf-8"><title>CapabilityTable Input · original isolation</title><link rel="stylesheet" href="capabilitytable-original.css"><style>.fixture{position:absolute;left:30px;top:40px}.fixture *{animation:none!important;transition:none!important}.utilities{display:flex;gap:12px;height:40px}</style><div class="utilities"><button id="CapabilityTable-next" tabindex="-1">next</button><button id="CapabilityTable-mount" tabindex="-1">mount</button><button id="CapabilityTable-record" tabindex="-1">record</button></div><button id="CapabilityTable-focus" tabindex="-1">focus</button><div id="fixtures"></div><script>'+script+'</script>')
print('Literal table parent four input cases prepared')
